MAX_TRIES = 6
WORD_LEN = 5


def daily_word():
    """Deterministic word of the day (same for everyone on the same date)."""
    return WORDS[datetime.date.today().toordinal() % len(WORDS)]


def feedback(guess, answer):
    """Standard Wordle scoring: green, then yellow with duplicate handling."""
    marks = [GREY] * WORD_LEN
    counts = {}
    for i in range(WORD_LEN):
        if guess[i] == answer[i]:
            marks[i] = GREEN
        else:
            counts[answer[i]] = counts.get(answer[i], 0) + 1
    for i in range(WORD_LEN):
        if marks[i] == GREY and counts.get(guess[i], 0) > 0:
            marks[i] = YELLOW
            counts[guess[i]] -= 1
    return marks


def render(guess, marks):
    return "".join(f"{m} {c} {RESET}" for c, m in zip(guess, marks))


def read_guess(turn):
    while True:
        try:
            guess = input(f"Guess {turn}/{MAX_TRIES}: ").strip().upper()
        except (EOFError, KeyboardInterrupt):
            print()
            sys.exit(0)
        if len(guess) != WORD_LEN or not guess.isalpha():
            print("  Please enter exactly 5 letters.")
        elif guess not in WORDS:
            print("  Not in the word list. Try another word.")
        else:
            return guess


def main():
